// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    address owner = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;

    function setUp() public { c = new EBU(); }

    function testFuzz_property(address to, uint256 amount) public {
        // admissible: any non-zero address recipient, amount scaled stays within uint256
        vm.assume(to != address(0));
        vm.assume(amount <= type(uint256).max / 1e18);

        address[] memory tos = new address[](1);
        tos[0] = to;
        uint256[] memory vs = new uint256[](1);
        vs[0] = amount;

        vm.prank(owner);
        bool ok = c.transfer(tos, vs);

        // General rule: a successful (non-reverting) transfer always returns true.
        assertTrue(ok, "completed transfer must return true");
    }
}
